<script setup>
import {computed,ref} from 'vue';import {storeToRefs} from 'pinia';import {useApp} from '../stores/app';import {money} from '../services/storage';import {useRouter} from 'vue-router';import ProductCard from './ProductCard.vue';
const props=defineProps({cashier:Boolean});const s=useApp(),router=useRouter(),cash=ref(''),method=ref('Tunai'),customer=ref(null),message=ref(''),success=ref(false),search=ref(''),category=ref('Semua');
const {draft:cart}=storeToRefs(s);
const categories=computed(()=>['Semua',...new Set(s.data.menu.filter(p=>p.active).map(p=>p.category))]);
const items=computed(()=>s.data.menu.filter(p=>p.active&&(category.value==='Semua'||p.category===category.value)&&(p.name+' '+p.variant).toLowerCase().includes(search.value.toLowerCase())));
const lines=computed(()=>s.data.menu.filter(p=>cart.value[p.id]>0)),total=computed(()=>lines.value.reduce((a,p)=>a+p.price*cart.value[p.id],0)),count=computed(()=>lines.value.reduce((a,p)=>a+cart.value[p.id],0));
function add(p){cart.value[p.id]=Math.min(99,(cart.value[p.id]||0)+1);message.value=''}
function minus(p){if(cart.value[p.id]>1)cart.value[p.id]--;else delete cart.value[p.id]}
function pay(){if(!s.user){router.push('/login');return}try{s.checkout(cart.value,props.cashier?method.value:'QRIS simulasi',Number(cash.value),props.cashier?customer.value:s.uid);success.value=true;message.value='Pesanan berhasil! Nomor antrean '+s.data.orders.at(-1).queue;cart.value={};cash.value=''}catch(e){success.value=false;message.value=e.message}}
const canOrder=computed(()=>props.cashier||!s.user||s.user.role==='customer');
</script>
<template><div class="ordering" :class="{'with-cart':canOrder}"><section class="menu-area"><div class="menu-tools"><input v-model="search" placeholder="Cari minuman..." aria-label="Cari minuman"><div class="category-tabs"><button v-for="c in categories" :key="c" type="button" :class="{chosen:category===c}" @click="category=c">{{c}}</button></div></div><div class="products order-products"><ProductCard v-for="p in items" :key="p.id" :product="p" :selectable="canOrder" @select="add"/></div><p v-if="!items.length" class="empty">Menu tidak ditemukan.</p></section><form v-if="canOrder" class="card checkout-panel" @submit.prevent="pay"><div class="spread"><h2>Pesanan saat ini</h2><small>{{count}} item</small></div><p v-if="!lines.length" class="empty">Keranjang kosong. Pilih minuman favoritmu.</p><div v-for="p in lines" :key="p.id" class="cart-line"><b>{{p.name}}</b><small>{{p.variant}}</small><div class="spread"><div class="qty"><button type="button" @click="minus(p)" aria-label="Kurangi">−</button><span>{{cart[p.id]}}</span><button type="button" @click="add(p)" aria-label="Tambah">+</button></div><strong>{{money(p.price*cart[p.id])}}</strong></div></div><div class="spread total"><b>Total pembayaran</b><strong>{{money(total)}}</strong></div><template v-if="cashier"><label>Pelanggan<select v-model="customer"><option :value="null">Walk-in</option><option v-for="u in s.data.users.filter(u=>u.role==='customer')" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>Pembayaran<select v-model="method"><option>Tunai</option><option>QRIS simulasi</option></select></label><label v-if="method==='Tunai'">Uang diterima<input type="number" min="0" step="1" v-model.number="cash"><small>Kembalian: {{money(Math.max(0,Number(cash)-total))}}</small></label></template><p v-else class="muted">Pembayaran QRIS simulasi · tidak ada uang sungguhan yang ditagihkan.</p><button :disabled="!count" class="checkout-button">{{!s.user?'Masuk untuk memesan':cashier?'Bayar & buat antrean':'Pesan sekarang'}}</button><p v-if="message" :class="success?'success-message':'error'" role="status">{{message}}</p><router-link v-if="success" to="/orders" class="order-link">Lihat status pesanan →</router-link></form></div></template>
